<?php foreach($db->query("SELECT s.id,s.nombre,s.telefono,s.estado,COUNT(*) n,SUM(r.monto) d,MIN(r.periodo) o FROM socios s JOIN recibos r ON r.socio_id=s.id AND r.estado='pendiente' GROUP BY s.id ORDER BY n DESC") as $r){$mes=(date('Y')-(int)substr($r['o'],0,4))*12+date('n')-(int)substr($r['o'],5,2);
echo'<tr><td>'.h($r['nombre']).'</td><td>'.h($r['telefono']).'</td><td>'.$r['n'].'</td><td>S/ '.number_format($r['d'],2).'</td><td>'.$mes.' mes(es) desde '.h($r['o']).'</td><td>'.h($r['estado']).'</td><td><a href="?doc=aviso&id='.$r['id'].'">Aviso</a> <a href="?doc=corte&id='.$r['id'].'">Orden</a> ';
echo'<form method="post" style="display:inline;border:0;box-shadow:none;padding:0;margin:0;background:none">'.tk().($r['estado']=='activo'?'<button class="red" name="cortar" value="'.$r['id'].'">Cortar</button>':'<button name="reconectar" value="'.$r['id'].'">Reconectar</button>').'</form></td></tr>';}?></table>
